const fs = require('node:fs')
const ts = require('typescript')
const source = fs.readFileSync('src/core/ledger.ts', 'utf8')
const compiled = ts.transpileModule(source, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 },
}).outputText
fs.writeFileSync(
  'cloudfunctions/ledger/core.cjs',
  '// Generated by scripts/build-cloud.cjs. Edit src/core/ledger.ts instead.\n' + compiled,
)
console.log('Cloud shared validation generated')
